import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card } from 'react-bootstrap';
import { 
  FaFish, FaWater, FaHandHoldingWater, FaLightbulb,
  FaUsers, FaLeaf, FaHeart, FaMapMarkerAlt,
  FaPhone, FaEnvelope, FaTint, FaSeedling,
  FaShippingFast, Recycle
} from 'react-icons/fa';

const Home = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  return (
    <div className="home-page">
      {/* Hero Section */}
      <section className="home-hero">
        <div className="hero-overlay"></div>
        <Container>
          <Row className="justify-content-center align-items-center min-vh-100">
            <Col lg={8} className="text-center">
              <div className="hero-content">
                <div className="water-reflection"></div>
                <h1 className="hero-title">
                  BUKANI MAMA TOTO
                </h1>
                <p className="hero-subtitle">
                  Women in Aquaculture - Transforming Lives Along Lake Victoria
                </p>
                <p className="hero-text">
                  Empowering women through sustainable tilapia farming, 
                  providing fresh fish to communities across the country.
                </p>
                <div className="hero-icons">
                  <FaFish className="icon" />
                  <FaWater className="icon" />
                  <FaHandHoldingWater className="icon" />
                  <FaLightbulb className="icon" />
                </div>
              </div>
            </Col>
          </Row>
        </Container>
      </section>

      {/* Mission Section */}
      <section className="py-5 mission-section">
        <Container>
          <h2 className="text-center mb-5 section-title">Our Mission</h2>
          
          <Row className="g-4">
            <Col md={4}>
              <Card className="mission-card glass-card h-100">
                <div className="card-icon">
                  <FaUsers />
                </div>
                <Card.Body className="text-center">
                  <Card.Title className="card-title">Women Empowerment</Card.Title>
                  <Card.Text>
                    Creating economic opportunities for women through tilapia farming, 
                    promoting financial independence and leadership in aquaculture.
